const H = height, R = radius, b = bulge, n = 12, rim = Math.min(0.03, H * 0.04), rec = 0.92;
const r = (y) => R * (1 + b * (1 - Math.pow(2 * y / H - 1, 2)));
const pts = [addpoint(0, [0, 0, 0])];
for (let i = 0; i <= n; i++) { const y = H * i / n; pts.push(addpoint(0, [r(y), y, 0])); }
pts.push(addpoint(0, [R * rec, H, 0]), addpoint(0, [R * rec, H - rim, 0]), addpoint(0, [0, H - rim, 0]));
addprim(0, 'polyline', pts);

const H = height, R = radius, b = bulge, n = Math.round(hoops), hh = Math.min(0.035, H * 0.04);
