for (let i = 0; i < n; i++) {
  const f = n === 1 ? 0.5 : i < n / 2 ? 0.08 + 0.3 * i / Math.max(1, Math.ceil(n / 2) - 1 || 1) : 0.92 - 0.3 * (n - 1 - i) / Math.max(1, Math.ceil(n / 2) - 1 || 1);
  const y = H * Math.min(0.94, Math.max(0.06, f));
